import SwiftUI
struct MyQuizzesView:View{@State private var store=MyQuizzesStore();@State private var create=false
 var body:some View{Group{if store.quizzes.isEmpty{ContentUnavailableView("Нет своих опросников",systemImage:"square.and.pencil",description:Text("Создай первый материал."))}else{List(store.quizzes){q in VStack(alignment:.leading,spacing:6){Text(q.title).font(.headline);if let d=q.description{Text(d).foregroundStyle(.secondary)};HStack{Text("Версия \(q.version_number)");Spacer();if let status=q.submission_status{Text(status)}else{Button("На модерацию"){Task{await store.submit(q)}}}}.font(.caption)}}}}.navigationTitle("Мои опросники").toolbar{Button{create=true}label:{Image(systemName:"plus")}}.sheet(isPresented:$create,onDismiss:{Task{await store.refresh()}}){CreateQuizView()}.task{await store.refresh()}.refreshable{await store.refresh()}}
}
